const getShortName = (name: string) => {
    if (!name) return '';
    const words = name.split(' ');
    if (words.length <= 2) return name;
    return words.slice(0, 2).join(' ') + '...';
};

const parseSafeDate = (dt: string | null | undefined): string => {
    if (!dt || dt === 'N/A' || dt === '-') return new Date().toISOString();
    const dtStr = String(dt);
    if (dtStr.includes('T') || dtStr.includes('Z')) return dtStr;
    return `${dtStr.replace(' ', 'T')}Z`;
};

const getHistoryDate = (order: Order | null, keywords: string[], trackingId?: string | null): string | null => {
    if (!order || !order.status_histories || order.status_histories.length === 0) return null;
    let histories = order.status_histories;

    // If a specific tracking ID is provided, prioritize histories mentioning it in the comment
    if (trackingId) {
        const specificMatch = histories
            .filter(h =>
                (h.status && keywords.some(k => h.status.toLowerCase().includes(k.toLowerCase()))) &&
                (h.comment && h.comment.toLowerCase().includes(trackingId.toLowerCase()))
            )
            .sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime())[0];

        if (specificMatch) return specificMatch.created_at;
    }

    const match = histories
        .filter(h => h.status && keywords.some(k => h.status.toLowerCase().includes(k.toLowerCase())))
        .sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime())[0];
    return match ? match.created_at : null;
};

const normalizeStatusLabel = (status: string | null | undefined): string => {
    if (!status) return '-';
    // Clean literal unicode escapes for all statuses
    let s = String(status).replace(/\\u00e9/g, 'é').replace(/\\u00c9/g, 'É');
    const low = s.toLowerCase().trim();

    // ONLY unify literal "Livr**" variants to "Livrée"
    if (['livree', 'livrée'].some(k => low === k || low.includes(k))) return 'Livrée';
    
    // For all other statuses (including complete, success), keep them as they are
    return s;
};

