    const sortedRows = useMemo(() => {
        const flatItems: any[] = [];
        
        orders.forEach(order => {
            // Pre-calculate totals per bordereau for this order
            const bordereauSums = new Map<string, number>();
            const bordereauShipping = new Map<string, number>();
            
            order.items.forEach(i => {
                const bId = i.bordereau_id || order.tracking_number || '';
                const itemTotal = Number(i.price || 0) * Number(i.qty_ordered || 1);
                bordereauSums.set(bId, (bordereauSums.get(bId) || 0) + itemTotal);
                if (i.frais_livraison !== undefined) {
                    bordereauShipping.set(bId, Number(i.frais_livraison));
                }
            });

            const processingItems = order.items.filter(item => {
                // CRITICAL FIX: If searching, include EVERYTHING of the matched order
                if (searchTerm) return true;

                const st = (item.custom_status || order.status_label || order.status).toLowerCase();
                
                if (filterStatus === 'all') {
                    return [
                        'processing', 'en cours', 'livraison en cours', 'processing_arkan',
                        'pickup_done', 'livraison_encours', 'livree', 'livrée',
                        'client_nondisp1', 'holded', 'retour_refusclient',
                        'success', 'complete', 'canceled', 'annule', 'annulé', 'colis ramassé'
                    ].some(k => st.includes(k));
                }

                // Standardized variations mapping
                const variations: { [key: string]: string[] } = {
                    'livree': ['livree', 'livrée', 'complete', 'success', 'paiement accepté'],
                    'processing': ['processing', 'en cours', 'processing_arkan'],
                    'pickup_done': ['pickup_done', 'pickup réalisé', 'colis ramassé'],
                    'livraison_encours': ['livraison_encours', 'livraison en cours'],
                    'canceled': ['canceled', 'annule', 'annulée', 'annulé', 'closed'],
                    'holded': ['holded', 'on hold'],
                    'client_nondisp1': ['client_nondisp1', 'client non disponible'],
                    'retour_refusclient': ['retour_refusclient', 'refusé par client'],
                    'confirmée': ['confirmée', 'confirmee', 'confirmed', 'validé', 'validee'],
                    'pending': ['pending']
                };

                const allowed = variations[filterStatus] || [filterStatus];
                return allowed.some(v => st.includes(v.toLowerCase()));
            });

            // If a specific filter is active, only process this order if it has matching items
            // CRITICAL FIX: Bypass status filter if searching to ensure specific search results show up
            if (filterStatus !== 'all' && !searchTerm && processingItems.length === 0) {
                return;
            }

            const validItems = processingItems;
            const seenBordereaux = new Set<string>();

            validItems.forEach((item, index) => {
                const currentBordereauId = item.bordereau_id || order.tracking_number || '';

                if (seenBordereaux.has(currentBordereauId)) return;
                seenBordereaux.add(currentBordereauId);

                const bordereauTotal = bordereauSums.get(currentBordereauId) || 0;
                const shippingCost = bordereauShipping.has(currentBordereauId) 
                    ? bordereauShipping.get(currentBordereauId)! 
                    : Number(order.frais_livraison || 0);
                
                const netSubtotal = bordereauTotal;
                const grandTotal = netSubtotal + shippingCost;

                const itemSeller = item.seller_name || item.vendor;
                const sellerName = (itemSeller && itemSeller !== 'Arkan') 
                    ? itemSeller 
                    : (order.items.find(i => i.seller_name && i.seller_name !== 'Arkan')?.seller_name || order.seller_name || 'Arkan');

                // CRITICAL FIX: Bypass seller and 3PL filters if searching
                if (filterSeller !== 'all' && !searchTerm && sellerName !== filterSeller) return;

                const current3PL = (currentBordereauId || '').startsWith('ARK-') ? 'Arkan' : (order.carrier && order.carrier !== 'N/A' ? order.carrier : 'En attente');
                if (filter3pl !== 'all' && !searchTerm && current3PL.toLowerCase() !== filter3pl.toLowerCase()) return;

                flatItems.push({
                    order,
                    item,
                    isFirstOfOrder: index === 0,
                    incrementId: order.increment_id,
                    trackingOrBordereau: currentBordereauId,
                    statusDisplay: item.custom_status || order.status_label || order.status,
                    seller: sellerName,
                    totalSortValue: grandTotal,
                    netSubtotalSortValue: netSubtotal,
                    productName: item.name,
                    contact: `${order.customer_firstname} ${order.customer_lastname}`,
                    location: order.billing_address?.city || '',
                    dateValue: item.processing_at || order.processing_at || item.bordereau_date || order.bordereau_date || item.confirmed_at || order.confirmed_at || order.created_at,
                    bordereauTotal,
                    netSubtotal,
                    grandTotal
                });
            });
        });

        if (!sortConfig) return flatItems;

        const { key, direction, type } = sortConfig;
        return [...flatItems].sort((a, b) => {
            let aValue, bValue;

            switch (key) {
                case 'order': aValue = a.incrementId; bValue = b.incrementId; break;
                case 'tracking': aValue = a.trackingOrBordereau; bValue = b.trackingOrBordereau; break;
                case 'status': aValue = a.statusDisplay; bValue = b.statusDisplay; break;
                case 'seller': aValue = a.seller; bValue = b.seller; break;
                case 'netSubtotal': aValue = a.netSubtotalSortValue; bValue = b.netSubtotalSortValue; break;
                case 'grandTotal': aValue = a.totalSortValue; bValue = b.totalSortValue; break;
                case 'product': aValue = a.productName; bValue = b.productName; break;
                case 'contact': aValue = a.contact; bValue = b.contact; break;
                case 'location': aValue = a.location; bValue = b.location; break;
                case 'date': aValue = a.dateValue; bValue = b.dateValue; break;
                default: return 0;
            }

            if (aValue === bValue) return 0;
            if (aValue === null || aValue === undefined) return 1;
            if (bValue === null || bValue === undefined) return -1;

            if (type === 'number') {
                return direction === 'asc' ? Number(aValue) - Number(bValue) : Number(bValue) - Number(aValue);
            }

            if (type === 'date') {
                const aTime = new Date(aValue as string).getTime();
                const bTime = new Date(bValue as string).getTime();
                return direction === 'asc' ? aTime - bTime : bTime - aTime;
            }

            const result = String(aValue).localeCompare(String(bValue), undefined, { numeric: true, sensitivity: 'base' });
            return direction === 'asc' ? result : -result;
        });
    }, [orders, sortConfig, filterStatus, filterSeller, filter3pl, searchTerm]);

