import React, { useMemo } from 'react';

const formatFR = (date: Date) => {
    return date.toLocaleString('fr-FR', {
        day: 'numeric',
        month: 'long',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
    });
};

interface TrackingEvent {
    id: number;
    waybill_number: string;
    status_code: string;
    status_description: string;
    location: string;
    comment: string;
    occured_at: string;
}

interface Props {
    history: TrackingEvent[];
    currentStatus?: string;
}

const TrackingStatusMap: React.FC<Props> = ({ history, currentStatus }) => {
    // Sort history by date ascending for the timeline
    const sortedHistory = useMemo(() => {
        return [...history].sort((a, b) => new Date(a.occured_at).getTime() - new Date(b.occured_at).getTime());
    }, [history]);

    if (sortedHistory.length === 0) {
        return (
            <div className="d-flex flex-column align-items-center justify-content-center p-10 border border-dashed rounded bg-light">
                <i className="ki-duotone ki-delivery-3 fs-3x text-muted mb-3"><span className="path1"></span><span className="path2"></span><span className="path3"></span></i>
                <span className="text-muted fw-bold">Aucun historique de suivi disponible pour le moment.</span>
            </div>
        );
    }

    // SVG Drawing constants - MORE VERTICAL SPACE
    const height = 300; // Increased from 220 for top/down room
    const stepWidth = 130;
    const paddingLeft = 100;
    const paddingRight = 120;
    const width = Math.max(700, sortedHistory.length * stepWidth + paddingLeft + paddingRight);
    
    // Generate points - centered vertically with more padding
    const points = sortedHistory.map((_, index) => {
        const x = paddingLeft + index * stepWidth;
        // Centered more precisely with 15px oscillation
        const y = height / 2 + (index % 2 === 0 ? -15 : 15);
        return { x, y };
    });

    const drawPath = () => {
        if (points.length < 2) return "";
        let path = `M ${points[0].x} ${points[0].y}`;
        for (let i = 0; i < points.length - 1; i++) {
            const p0 = points[i];
            const p1 = points[i + 1];
            const cp1x = p0.x + stepWidth / 2;
            const cp1y = p0.y;
            const cp2x = p1.x - stepWidth / 2;
            const cp2y = p1.y;
            path += ` C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${p1.x} ${p1.y}`;
        }
        return path;
    };

    return (
        <div className="tracking-status-map-container overflow-auto" style={{ width: '100%', backgroundColor: '#f9fafb', borderRadius: '15px', border: '1px solid #e4e6ef' }}>

            <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} style={{ display: 'block' }}>
                <defs>
                    <pattern id="dotGrid" x="0" y="0" width="30" height="30" patternUnits="userSpaceOnUse">
                        <circle cx="2" cy="2" r="1" fill="#e4e6ef" />
                    </pattern>

                    <linearGradient id="mainPathGradient" x1="0%" y1="0%" x2="100%" y2="0%">
                        <stop offset="0%" stopColor="#f64e60" stopOpacity="0.8" />
                        <stop offset="50%" stopColor="#ffa800" stopOpacity="0.9" />
                        <stop offset="100%" stopColor="#3699ff" stopOpacity="1" />
                    </linearGradient>

                    <filter id="cardShadow" x="-20%" y="-20%" width="140%" height="140%">
                        <feGaussianBlur in="SourceAlpha" stdDeviation="5" />
                        <feOffset dx="0" dy="5" result="offsetblur" />
                        <feComponentTransfer><feFuncA type="linear" slope="0.08" /></feComponentTransfer>
                        <feMerge><feMergeNode /><feMergeNode in="SourceGraphic" /></feMerge>
                    </filter>
                </defs>

                {/* Background Grid */}
                <rect width={width} height={height} fill="url(#dotGrid)" />

                {/* Milestone 1: Arkan (Start) */}
                <g transform={`translate(${paddingLeft - 70}, ${height / 2 - 25})`}>
                    <rect width="50" height="50" rx="12" fill="#fff" stroke="#e4e6ef" />
                    <text x="25" y="32" textAnchor="middle" style={{ fontSize: '20px' }}>🏢</text>
                    <text x="25" y="65" textAnchor="middle" fill="#3699ff" style={{ fontSize: '9px', fontWeight: '900', textTransform: 'uppercase' }}>Arkan</text>
                </g>

                {/* Journey Line (Base) */}
                <path d={drawPath()} fill="none" stroke="#e4e6ef" strokeWidth="5" strokeLinecap="round" />
                
                {/* Journey Line (Animated Gradient) */}
                <path d={drawPath()} fill="none" stroke="url(#mainPathGradient)" strokeWidth="3" strokeDasharray="10 6" className="moving-path" />

                {/* Milestones (Hub Stops) */}
                {points.map((pt, idx) => {
                    const event = sortedHistory[idx];
                    const isLast = idx === points.length - 1;
                    const isEven = idx % 2 === 0;
                    
                    const stepColors = ["#3699ff", "#7239ea", "#00cbc2", "#181c32", "#f64e60"];
                    const stepColor = isLast ? "#3699ff" : stepColors[idx % stepColors.length];

                    return (
                        <g key={event.id}>
                            {/* Horizontal Connector Line */}
                            <line 
                                x1={pt.x} 
                                y1={pt.y} 
                                x2={pt.x} 
                                y2={isEven ? pt.y - 35 : pt.y + 35} 
                                stroke={stepColor} 
                                strokeWidth="1.5" 
                                strokeDasharray="3 2"
                                opacity="0.4"
                            />

                            {/* Hub Bead */}
                            <circle cx={pt.x} cy={pt.y} r={isLast ? "8" : "5"} fill={isLast ? stepColor : "#fff"} stroke={stepColor} strokeWidth={isLast ? "3" : "2"} />
                            
                            {isLast && (
                                <circle cx={pt.x} cy={pt.y} r="14" fill="none" stroke={stepColor} strokeWidth="2" className="ping-ring" />
                            )}

                            {/* Professional Glassmorphic Label Card (Light) */}
                            <g transform={`translate(${pt.x - 75}, ${isEven ? pt.y - 125 : pt.y + 35})`} filter="url(#cardShadow)">
                                <rect width="150" height="75" rx="16" fill="rgba(255, 255, 255, 0.95)" stroke="rgba(0, 0, 0, 0.05)" style={{ backdropFilter: 'blur(10px)' }} />
                                {/* Bottom Accent line */}
                                <rect x="20" y="71" width="110" height="2" rx="1" fill={stepColor} opacity="0.6" />
                                
                                <text x="12" y="24" fill="#181c32" style={{ fontSize: '11px', fontWeight: '900', letterSpacing: '-0.2px' }}>
                                    {event.status_description.length > 20 ? event.status_description.substring(0, 18) + '...' : event.status_description}
                                </text>
                                <text x="12" y="44" fill={stepColor} style={{ fontSize: '10px', fontWeight: '700' }}>
                                    📍 {event.location || 'Hub'}
                                </text>
                                <text x="12" y="60" fill="#7e8299" style={{ fontSize: '9px', fontWeight: '500' }}>
                                    📅 {formatFR(new Date(event.occured_at))}
                                </text>
                            </g>
                        </g>
                    );
                })}

                {/* Milestone 2: Client (End Goal) */}
                <g transform={`translate(${points[points.length-1].x + 60}, ${height / 2 - 25})`}>
                    <rect width="50" height="50" rx="12" fill="#fff" stroke="#e4e6ef" />
                    <text x="25" y="32" textAnchor="middle" style={{ fontSize: '20px' }}>🏠</text>
                    <text x="25" y="65" textAnchor="middle" fill="#3699ff" style={{ fontSize: '9px', fontWeight: 'bold', textTransform: 'uppercase' }}>Client</text>
                </g>
            </svg>

            <style>{`
                .moving-path {
                    stroke-dashoffset: 1000;
                    animation: flowPath 25s linear infinite;
                }
                @keyframes flowPath {
                    to { stroke-dashoffset: 0; }
                }
                .ping-ring {
                    animation: pingScale 2s infinite;
                    transform-origin: center;
                }
                @keyframes pingScale {
                    from { transform: scale(0.5); opacity: 1; }
                    to { transform: scale(1.5); opacity: 0; }
                }
                .tracking-status-map-container::-webkit-scrollbar {
                    height: 5px;
                }
                .tracking-status-map-container::-webkit-scrollbar-thumb {
                    background: #e1e3ea;
                    border-radius: 10px;
                }
                .tracking-status-map-container::-webkit-scrollbar-track {
                    background: #f1f1f4;
                }
            `}</style>
        </div>
    );
};

export default TrackingStatusMap;
